	/** 
	 * jumpstart the process by instantiating2 Customer
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		customerId = CustomerService.getCustomerInstance()
		.createCustomer( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CustomerService.getCustomerInstance()
				.createCustomer( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.customerSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Customer : " + successValue.getCustomerId());
							  if (successValue.getCustomerId().equals(customerId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCustomerList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Customer test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on customer consumed")
					);
			subscriber.customerSubscribe( customerId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Customer : " + successValue.getCustomerId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCustomerList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on customer for customerId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Customer. 
	 */
	protected Customer read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Customer" );

		Customer entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Customer with primary key" );
		msg.append( customerId );
		
		CustomerFetchOneSummary fetchOneSummary = new CustomerFetchOneSummary( customerId );

		try {
			entity = CustomerService.getCustomerInstance().getCustomer( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Customer " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Customer.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Customer." );

		StringBuilder msg = new StringBuilder( "Failed to update a Customer : " );        
		Customer entity = read();
		UpdateCustomerCommand command = generateUpdateCommand();
		command.setCustomerId(entity.getCustomerId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Customer." );

			// for use later on...
			customerId = entity.getCustomerId();

			CustomerService proxy = CustomerService.getCustomerInstance();  

			proxy.updateCustomer( command ).get();

			LOGGER.info( "-- Successfully saved Customer - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + customerId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Customer.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Customer." );

		Customer entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Customer with id " + customerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Customer with id " + customerId );

			throw e;
		}

		try{
			CustomerService.getCustomerInstance().delete( new DeleteCustomerCommand( entity.getCustomerId() ) ).get();
			LOGGER.info( "-- Successfully deleted Customer with id " + customerId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Customer with id " + customerId );

			throw e;
		}
	}

	/**
	 * get all Customers.
	 */
	protected List<Customer> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Customers:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Customer : " );        
		List<Customer> collection  = new ArrayList<>();

		try {
			// call the static get method on the CustomerService
			collection = CustomerService.getCustomerInstance().getAllCustomer();
			assertNotNull( collection, "An Empty collection of Customer was incorrectly returned.");
			
			// Now print out the values
			Customer entity = null;            
			Iterator<Customer> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCustomerId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

